import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int height = scanner.nextInt();
        int target = scanner.nextInt();

        int start = 1;
        int end = (int) Math.pow(2, height);
        int steps = 0;
        int state = 0;

        while (start < end) {
            int mid_point = (start + end) / 2;
            if (target <= mid_point) {
                if (state == 0) {
                    steps += 1;
                    state = 1;
                } else {
                    steps += (int) Math.pow(2, height);
                }
                end = mid_point;
            } else {
                if (state == 1) {
                    steps += 1;
                    state = 0;
                } else {
                    steps += (int) Math.pow(2, height);
                }
                start = mid_point + 1;
            }
            height -= 1;
        }

        System.out.println(steps);
    }
}
